SourceCode.Declaration:
/* ================================================================================ METSalesOrderCancellationContract ================================================================================ SysOperationFramework data contract.
Fields: LegalEntityScope - multi-select. Empty = all enabled companies. SalesIdScope - multi-select. Empty = all eligible (flagged, open) sales orders within the legal entity scope. MaxRetryCount - retries allowed on a transient UpdateConflict before an order/line is skipped for this run (left flagged for the next run). Default 3.
Both LegalEntityScope and SalesIdScope are advisory at the dialog level - METSalesOrderCancellationService re-validates both server-side (see isCompanyInScope / isSalesIdInScope), and only ever actually processes records that genuinely carry METOrderCancellationRequired = Yes or METLineCancellationRequired = Yes, regardless of what's selected here.
The interactive multi-select behavior (pickers + "changing legal entity clears sales order selection") is wired in METSalesOrderCancellationUIBuilder, attached below via SysOperationUIBuilderAttribute. ================================================================================ */ [ DataContractAttribute, SysOperationContractProcessingAttribute( classStr(METSalesOrderCancellationUIBuilder)) ] public class METSalesOrderCancellationContract { Container legalEntityScope; Container salesIdScope; Integer maxRetryCount;
}

Method.Source:
[
    DataMemberAttribute('LegalEntityScope'),
    SysOperationLabelAttribute(literalStr('Legal entity')),
    SysOperationHelpTextAttribute(
        literalStr('Optional. Leave blank to process all enabled legal entities.')),
    SysOperationDisplayOrderAttribute('1')
]
public Container parmLegalEntityScope(
    Container _legalEntityScope = legalEntityScope)
{
    legalEntityScope = _legalEntityScope;
    return legalEntityScope;
}

[
    DataMemberAttribute('SalesIdScope'),
    SysOperationLabelAttribute(literalStr('Sales order')),
    SysOperationHelpTextAttribute(
        literalStr('Optional. Select legal entities first to choose specific eligible sales orders. Leave blank to process all flagged orders in scope.')),
    SysOperationDisplayOrderAttribute('2')
]
public Container parmSalesIdScope(
    Container _salesIdScope = salesIdScope)
{
    salesIdScope = _salesIdScope;
    return salesIdScope;
}

[
    DataMemberAttribute('MaxRetryCount'),
    SysOperationLabelAttribute(literalStr('Max retry count')),
    SysOperationHelpTextAttribute(
        literalStr('Number of retries allowed for a transient update conflict before the record is skipped for this run.')),
    SysOperationDisplayOrderAttribute('3')
]
public Integer parmMaxRetryCount(
    Integer _maxRetryCount = maxRetryCount)
{
    maxRetryCount = _maxRetryCount;
    return maxRetryCount;
}
